// One output item per usable attachment (PDF or image), carrying email metadata.
// If the email has no PDF attachment, the email body (HTML or plain text) is also sent for reading.
const OK = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp'];
const ODT = 'application/vnd.oasis.opendocument.text';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const OFFICE = [ODT, DOCX];
// Outlook often labels attachments as application/octet-stream: fall back to the file extension.
const EXT = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', odt: ODT, docx: DOCX };
const MIN_BODY_CHARS = 150;
function bodyToText(body) {
  if (!body) return '';
  const raw = typeof body === 'string' ? body : (body.content || '');
  const isHtml = typeof body === 'object' ? String(body.contentType || '').toLowerCase() === 'html' : /<[a-z][^>]*>/i.test(raw);
  if (!isHtml) return raw.trim();
  return raw
    .replace(/<(script|style|head)[^>]*>[^]*?<\/\1>/gi, ' ')
    .replace(/<br[^>]*>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6]|table)>/gi, '\n')
    .replace(/<\/(td|th)>/gi, ' | ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&pound;/gi, '£').replace(/&euro;/gi, '€').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n[ \n]*/g, '\n')
    .trim();
}
const out = [];
const all = $input.all();
for (let idx = 0; idx < all.length; idx++) {
  const item = all[idx];
  const j = item.json || {};
  const ea = (j.from && j.from.emailAddress) ? j.from.emailAddress : null;
  const fromRaw = ea ? (ea.name ? ea.name + ' <' + (ea.address || '') + '>' : (ea.address || '')) : ((j.from && j.from.text) ? j.from.text : (j.from ?? ''));
  const fromStr = typeof fromRaw === 'string' ? fromRaw : JSON.stringify(fromRaw);
  const m = fromStr.match(/[\w.+-]+@[\w.-]+\.\w+/);
  const meta = {
    from: fromStr,
    from_email: m ? m[0] : '',
    subject: j.subject ?? '',
    received_at: j.receivedDateTime ?? j.date ?? '',
    message_id: j.internetMessageId ?? j.messageId ?? (j.headers ? j.headers['message-id'] : '') ?? '',
    outlook_message_id: j.id ?? '',
    outlook_categories: Array.isArray(j.categories) ? j.categories : []
  };
  // Forwarded by the accounts inbox: use the original sender from the forwarded header.
  const accountsUpn = String(j.accounts_mailbox_upn || '').trim().toLowerCase();
  if (accountsUpn && meta.from_email.toLowerCase() === accountsUpn) {
    const fwdText = bodyToText(j.body);
    const re = /From:\s*([^\n<]*?)\s*<([\w.+-]+@[\w.-]+\.\w+)>/gi;
    let mm;
    while ((mm = re.exec(fwdText)) !== null) {
      if (mm[2].toLowerCase() !== accountsUpn) {
        meta.forwarded_by = meta.from;
        meta.from = (mm[1] ? mm[1].trim() + ' ' : '') + '<' + mm[2] + '>';
        meta.from_email = mm[2];
        break;
      }
    }
  }
  let found = 0;
  let hasPdf = false;
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const ext = String(bin.fileName || '').split('.').pop().toLowerCase();
    let mime = String(bin.mimeType || '').toLowerCase();
    if (!OK.includes(mime) && !OFFICE.includes(mime) && EXT[ext]) mime = EXT[ext];
    if (!OK.includes(mime) && !OFFICE.includes(mime)) continue;
    // Skip signature and logo images: tiny pictures and typical decorative file names are never invoices.
    if (mime.indexOf('image/') === 0) {
      const sm = /([\d.]+)\s*(bytes|kb|mb)/i.exec(String(bin.fileSize || ''));
      const kb = sm ? (/mb/i.test(sm[2]) ? parseFloat(sm[1]) * 1024 : /kb/i.test(sm[2]) ? parseFloat(sm[1]) : parseFloat(sm[1]) / 1024) : null;
      if ((kb !== null && kb < 15) || /^(image\d{3}|outlook-|logo|signature|banner|icon|facebook|linkedin|twitter|instagram)/i.test(String(bin.fileName || ''))) continue;
    }
    const isOffice = OFFICE.includes(mime);
    // Word/ODT files are read as text; keep the original so the invoice file itself can be saved.
    const original = isOffice ? (await this.helpers.getBinaryDataBuffer(idx, key)).toString('base64') : undefined;
    found++;
    if (mime === 'application/pdf' || isOffice) hasPdf = true;
    out.push({
      json: { ...meta, source_type: isOffice ? 'office_document' : 'attachment', filename: bin.fileName || key, mime_type: mime, has_attachment: true, has_document: true, ...(isOffice ? { original_base64: original } : {}) },
      // Word/ODT files are zip archives; mark them as zip so they can be unpacked to text.
      binary: { data: isOffice ? { ...bin, mimeType: mime, fileExtension: 'zip' } : { ...bin, mimeType: mime } },
      pairedItem: { item: idx }
    });
  }
  const bodyText = bodyToText(j.body).slice(0, 60000);
  if (!hasPdf && bodyText.length >= MIN_BODY_CHARS) {
    found++;
    out.push({
      json: { ...meta, source_type: 'email_body', filename: 'email-body.txt', mime_type: 'text/plain', body_text: bodyText, has_attachment: false, has_document: true },
      pairedItem: { item: idx }
    });
  }
  if (!found) out.push({ json: { ...meta, has_attachment: false, has_document: false }, pairedItem: { item: idx } });
}
return out;

// Pull the readable text out of an unpacked .odt (content.xml) or .docx (word/document.xml).
const NL = String.fromCharCode(10);
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = $('Word or ODT document?').itemMatching(i);
  const bins = items[i].binary || {};
  let xml = '';
  for (const key of Object.keys(bins)) {
    const name = String(bins[key].fileName || key).toLowerCase();
    if (name.endsWith('content.xml') || name.endsWith('document.xml')) {
      const buf = await this.helpers.getBinaryDataBuffer(i, key);
      xml = buf.toString('utf8');
      break;
    }
  }
  const text = xml
    .replace(new RegExp('<(text:tab|w:tab)[^>]*>', 'g'), ' ')
    .replace(new RegExp('<(text:line-break|w:br)[^>]*>', 'g'), NL)
    .replace(new RegExp('</(text:p|text:h|w:p)>', 'g'), NL)
    .replace(new RegExp('</(table:table-cell|w:tc)>', 'g'), ' | ')
    .replace(new RegExp('<[^>]+>', 'g'), '')
    .replace(new RegExp('&lt;', 'g'), '<').replace(new RegExp('&gt;', 'g'), '>')
    .replace(new RegExp('&quot;', 'g'), '"').replace(new RegExp('&apos;', 'g'), "'")
    .replace(new RegExp('&amp;', 'g'), '&')
    .trim()
    .slice(0, 60000);
  out.push({
    json: { ...src.json, source_type: 'document_text', body_text: text, document_text_found: text.length > 0 },
    pairedItem: { item: i }
  });
}
return out;

// Build the Anthropic Messages API request for each attachment.
const cfg = $('Config').first().json;
const SYSTEM = "You extract data from supplier invoices for a UK property management business. Return ONLY one JSON object. No markdown fences, no commentary.

Rules:
- Copy values exactly as printed. Never guess or infer a missing value; use null instead.
- Do NOT decide whether an invoice should be paid or approved.
- Do NOT work out which property a line belongs to. Copy any property reference (address, house name, flat or unit) exactly as written next to the line, or at invoice level if it is given only once.
- Dates as YYYY-MM-DD. Amounts as plain numbers (no currency symbols). Currency as a 3-letter code.
- suggested_category must be one of: Cleaning, Maintenance and repairs, Compliance and safety, Pest control, Waste removal, Furniture and setup, Utilities and broadband, Build and refurbishment, Professional fees, Software and subscriptions, Other.
- suggested_job_type must be one of: Changeover, Midstay, Deep clean, Call-out, Other, or null if unclear.
- Invoice decision (be explicit): set is_invoice to true ONLY for a supplier invoice or a supplier credit note. Set document_type to "invoice" for an invoice (including a VAT invoice or pro-forma that requests payment) and "credit_note" for a credit note (a document titled credit note, credit memo or credit, or one that reduces or refunds an earlier invoice).
- For a credit note: put the credit note number in invoice_number and its date in invoice_date, copy amounts as positive numbers exactly as printed (do not add minus signs), and put the number of the invoice it credits in credited_invoice_reference (null if not shown).
- Everything else (a logo, signature image, quote, estimate, statement of account, payment receipt or remittance, order confirmation, reminder letter, or other) is NOT an invoice: set is_invoice to false, set document_type to quote, statement, receipt or other, and fill only document_type and legibility_confidence.
- If you cannot tell whether the document is an invoice or credit note, set is_invoice to false and explain why in extraction_notes.

Schema:
{
  "is_invoice": true,
  "document_type": "invoice | credit_note | quote | statement | receipt | other",
  "credited_invoice_reference": null,
  "legibility_confidence": 0.0,
  "supplier": {
    "name": null, "address": null, "email": null, "phone": null,
    "vat_number": null, "company_number": null,
    "bank": {"account_name": null, "sort_code": null, "account_number": null, "iban": null}
  },
  "invoice_number": null,
  "invoice_date": null,
  "due_date": null,
  "quote_or_po_reference": null,
  "addressed_to": {"name": null, "address": null},
  "currency": "GBP",
  "lines": [
    {
      "description": null,
      "property_reference_as_written": null,
      "service_date": null,
      "quantity": null,
      "net": null, "vat": null, "gross": null,
      "suggested_category": null,
      "suggested_job_type": null
    }
  ],
  "totals": {"net": null, "vat": null, "gross": null},
  "payment_terms": null,
  "extraction_notes": []
}
legibility_confidence is your own 0 to 1 estimate of how clearly the whole document could be read. Put anything unclear, cut off, handwritten or ambiguous into extraction_notes.";
const hash53 = (str, seed = 0) => { let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed; for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36); };
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  let b64, block;
  if (typeof it.json.body_text === 'string') {
    const doc = 'From: ' + it.json.from + '
Subject: ' + it.json.subject + '
Received: ' + it.json.received_at + '

' + it.json.body_text;
    b64 = Buffer.from(doc, 'utf8').toString('base64');
    const intro = it.json.source_type === 'document_text'
      ? 'The invoice (if any) is in the attached document ' + it.json.filename + ', converted to plain text below together with the email details:'
      : 'The invoice (if any) is in the body of this email, not an attachment. Email content:';
    block = { type: 'text', text: intro + String.fromCharCode(10, 10) + doc };
  } else {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    b64 = buf.toString('base64');
    block = it.json.mime_type === 'application/pdf'
      ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
      : { type: 'image', source: { type: 'base64', media_type: it.json.mime_type, data: b64 } };
  }
  out.push({
    json: {
      ...it.json,
      document_base64: b64,
      // The invoice file itself (PDF, image, or the original Word/ODT), to save to SharePoint.
      file_base64: typeof it.json.body_text === 'string' ? (it.json.original_base64 || null) : b64,
      doc_hash: hash53(b64) + '-' + b64.length,
      requestBody: {
        model: cfg.model,
        max_tokens: 3000,
        temperature: 0,
        system: SYSTEM,
        messages: [{ role: 'user', content: [block, { type: 'text', text: 'Extract the invoice fields as specified. Return JSON only.' }] }]
      }
    },
    binary: it.binary
  });
}
return out;

// Parse the model reply and build the payload for the Hinkley app.
const cfg = $('Config').first().json;
// Reads the OpenAI reply (or a cached reading).
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const src = $('Build AI request').itemMatching(i).json;
  const isFallback = Array.isArray(resp.output);
  let extraction = null, extraction_error = null;
  try {
    if (resp.cached_extraction) { extraction = resp.cached_extraction; } else {
    if (resp.error) throw new Error(typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error));
    if (isFallback) {
      const parts = [];
      for (const o of resp.output) for (const c of (o.content || [])) parts.push(c.text);
      const first = parts.find(p => p !== undefined && p !== null);
      extraction = (first && typeof first === 'object') ? first : JSON.parse(String(parts.join('')).replace(/```json|```/g, '').trim());
    } else {
      const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
      extraction = JSON.parse(text.replace(/```json|```/g, '').trim());
    }
    }
  } catch (e) {
    extraction_error = String(e.message || e).slice(0, 500);
  }
  // Normalise the document type: stored documents are either 'invoice' or 'credit_note'.
  if (extraction && typeof extraction === 'object') {
    const dt = String(extraction.document_type || '').toLowerCase().replace(/[^a-z]/g, '');
    if (extraction.is_invoice === true) extraction.document_type = (dt === 'creditnote' || dt === 'credit' || dt === 'creditmemo') ? 'credit_note' : 'invoice';
  }
  const document_type = (extraction && extraction.is_invoice === true) ? extraction.document_type : ((extraction && extraction.document_type) || 'unknown');
  const usedModel = resp.cached_extraction ? 'cache' : cfg.model;
  const base = src.message_id || [src.from, src.subject, src.received_at].join('|');
  // Fingerprint of the invoice itself, so the same invoice sent again (e.g. forwarded) is skipped.
  const norm = v => String(v === null || v === undefined ? '' : v).toLowerCase().replace(/[^a-z0-9.]/g, '');
  let invoice_fingerprint = 'doc::' + base + '::' + src.filename;
  if (extraction && extraction.is_invoice === true) {
    const sup = extraction.supplier || {};
    const bank = sup.bank || {};
    const supplierKey = norm(bank.account_number) || norm(sup.vat_number) || norm(sup.name);
    const gross = extraction.totals && typeof extraction.totals.gross === 'number' ? extraction.totals.gross.toFixed(2) : '';
    if (supplierKey && (norm(extraction.invoice_number) || gross)) {
      // Without an invoice number or date, also use the file name so a repeat monthly charge of the same amount is not mistaken for a copy.
      const weak = !norm(extraction.invoice_number) && !norm(extraction.invoice_date);
      invoice_fingerprint = (document_type === 'credit_note' ? 'cn::' : 'inv::') + [supplierKey, norm(extraction.invoice_number), norm(extraction.invoice_date), gross].join('|') + (weak ? '|' + norm(src.filename) : '');
    }
  }
  out.push({
    json: {
      payload: {
        idempotency_key: base + '::' + src.filename,
        document_type,
        shadow_mode: cfg.shadow_mode,
        model: usedModel,
        extraction_provider: resp.cached_extraction ? 'cache' : 'openai',
        from_cache: !!resp.cached_extraction,
        doc_hash: src.doc_hash || '',
        source: {
          from: src.from, from_email: src.from_email, subject: src.subject,
          received_at: src.received_at, message_id: src.message_id,
          filename: src.filename, mime_type: src.mime_type, source_type: src.source_type
        },
        extraction,
        extraction_error,
        document_base64: src.document_base64,
        file_base64: src.file_base64 || null
      },
      invoice_fingerprint,
      document_type,
      outlook_message_id: src.outlook_message_id || '',
      outlook_categories: src.outlook_categories || []
    },
    pairedItem: { item: i }
  });
}
return out;

// Intake check for the accounts inbox. Rules decide; the AI only read the invoice.
// One verdict per email: pass | bounce (ask the sender to reissue) | review (a person looks; the sender is never contacted) | not_invoice.
const cfg = $('Config').first().json;
const mode = ['shadow', 'draft', 'live'].includes(String(cfg.mode)) ? String(cfg.mode) : 'shadow';
const NL = String.fromCharCode(10);
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const r2 = v => Math.round(v * 100) / 100;
const money = (n, c) => (c && c !== 'GBP' ? c + ' ' : '£') + Number(n).toFixed(2);
let companies = [];
try { companies = JSON.parse(cfg.company_names || '[]'); } catch (e) { companies = []; }
const normName = s => String(s || '').toLowerCase().replace(/hinckley/g, 'hinkley').replace(/\blimited\b/g, 'ltd').replace(/[^a-z0-9]+/g, ' ').trim();
// Other names an invoice may be addressed to, mapped to the Xero organisation they belong to.
// Read from Supabase (company_aliases, edited in the Hinkley app > Company aliases).
// "Ltd"/"Limited" on a name is optional. Add a name in the app - no workflow change needed.
let aliases = {}, aliasFileOk = false;
try {
  const rows = ($('Get company aliases').first().json || {}).aliases;
  if (Array.isArray(rows)) {
    for (const r of rows) { const a = String((r || {}).name_on_invoice || '').trim(), o = String((r || {}).xero_organisation || '').trim(); if (a && o) aliases[a] = o; }
    aliasFileOk = true;
  }
} catch (e) { aliasFileOk = false; }
const nameEntries = [];
for (const c of companies) { const n = normName(c); if (n) nameEntries.push({ pat: n, org: c }); }
for (const [alias, org] of Object.entries(aliases)) {
  const n = normName(alias); if (!n) continue;
  nameEntries.push({ pat: n, org: String(org) });
  const short = n.replace(/ ltd$/, '');
  if (short !== n && short.split(' ').length >= 2) nameEntries.push({ pat: short, org: String(org) });
}
nameEntries.sort((a, b) => b.pat.length - a.pat.length);   // longest (most specific) match wins
const matchCompany = raw => { const bt = ' ' + normName(raw) + ' '; const e = nameEntries.find(x => bt.includes(' ' + x.pat + ' ')); return e ? e.org : ''; };
// Aliases listed in Config hidden_alias_names are still accepted, but never shown to suppliers in a bounce email.
const hiddenNames = new Set(String(cfg.hidden_alias_names || '').split(',').map(s => normName(s)).filter(Boolean));
const acceptedNames = companies.concat(Object.keys(aliases).filter(a => !companies.includes(a)))
  .filter(a => !hiddenNames.has(normName(a)) && !hiddenNames.has(normName(a).replace(/ ltd$/, '')));
const companyNorm = nameEntries.map(e => e.pat);
const blocked = String(cfg.blocked_sender_patterns || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const internalDomain = String(cfg.internal_domain || '').toLowerCase();
const legMin = Number(cfg.legibility_min || 0.8);
const maxPerInvoice = Number(cfg.max_bounces_per_invoice || 2);
const maxPerSenderDay = Number(cfg.max_bounces_per_sender_per_day || 5);
// Internal emails (the [SHADOW] preview to the reviewer) are sent from the no-reply shared mailbox.
// Set noreply_address in Config. Bounces to suppliers still go out from the accounts mailbox.
const noreplyAddress = String(cfg.noreply_address || '').trim();

// ---- history (invoice_intake_checks in Supabase) ----
const hist = [];
try { for (const r of (($('Get intake log').first().json || {}).rows || [])) if (r && r.bounce_key !== undefined) hist.push(r); } catch (e) {}
const sentActions = ['bounce_sent', 'draft_created', 'shadow_proposed'];
const now = Date.now();

// ---- group the documents of each email ----
const groups = {};
const order = [];
for (const it of $('Parse extraction').all()) {
  const j = it.json || {};
  const p = j.payload || {};
  const s = p.source || {};
  const key = s.message_id || j.outlook_message_id || [s.from, s.subject, s.received_at].join('|');
  if (!groups[key]) { groups[key] = { key, source: s, outlook_message_id: j.outlook_message_id || '', categories: j.outlook_categories || [], docs: [] }; order.push(key); }
  groups[key].docs.push(p);
}

// ---- property reference test: a word is needed, a bare number is not enough ----
const STREET = new Set(['road', 'rd', 'street', 'st', 'avenue', 'ave', 'lane', 'ln', 'drive', 'dr', 'close', 'place', 'court', 'ct', 'flat', 'house', 'property', 'unit', 'es', 'e', 's']);
const refStatus = ref => {
  const t = String(ref || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
  if (!t.length) return 'missing';
  const words = t.filter(x => /[a-z]/.test(x) && !/^\d+[a-z]?$/.test(x) && !STREET.has(x));
  return words.length ? 'ok' : 'incomplete';
};

// ---- invoice sent as a link (no PDF attached) ----
// Apps like Invoice Simple, Xero and QuickBooks often email a "View invoice" button instead of attaching the PDF.
// The AI then sees only a notification and says it is not an invoice. Those emails go to review, never bounce.
const LINK_PLATFORMS = String(cfg.invoice_link_platforms || 'invoicesimple,getinvoicesimple,xero,quickbooks,intuit,sumup,zoho,freeagent,sage,stripe,squareup,paypal,invoice2go,waveapps,freshbooks,tide,kashflow,clearbooks,pandle,crunch,invoiceninja,zervant,bill.com')
  .toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const OWN_NAMES = String(cfg.own_trading_names || 'hinkley homes').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const NOT_A_BILL = /remittance|receipt|payment (received|confirmation|confirmed)|has been paid|statement|quot(e|ation)|estimate|credit note/i;
const linkInvoice = g => {
  const s = g.source || {};
  const subject = String(s.subject || '');
  let body = '';
  for (const p of g.docs) {
    const src = p.source || {};
    if (src.source_type === 'email_body' && p.document_base64) {
      try { body += '\n' + Buffer.from(String(p.document_base64), 'base64').toString('utf8'); } catch (e) {}
    }
  }
  if (NOT_A_BILL.test(subject)) return null;
  // Our own sales invoices (e.g. Xero "Bill INV-123 from Hinkley Homes is due" sent to a customer with accounts copied) are not bills to pay.
  const issuerM = subject.match(/\bfrom\s+(.+?)(?:\s+is\s+(?:due|overdue)|\s+for\s|\s*$)/i);
  const issuer = (issuerM ? issuerM[1] : '').toLowerCase();
  const senderName = String(s.from || '').replace(/<[^>]*>/, '').trim().toLowerCase();
  if (OWN_NAMES.some(o => issuer.indexOf(o) >= 0 || senderName.indexOf(o) >= 0)) return null;
  const invoiceWord = /\binvoice\b|\binv[-\s#]?\d/i;
  if (!invoiceWord.test(subject) && !invoiceWord.test(body)) return null;
  const linkPhrase = /(view|download|open|see|access|pay)\s+(your\s+|the\s+|this\s+)?(pdf\s+)?invoice|click (below|here|the (button|link))[^\n]{0,60}invoice|invoice[^\n]{0,40}\b(link|online|portal)\b/i;
  const dom = String(s.from_email || '').toLowerCase().split('@')[1] || '';
  const platform = LINK_PLATFORMS.find(pl => dom.indexOf(pl) >= 0 || body.toLowerCase().indexOf(pl + '.') >= 0);
  if (!linkPhrase.test(body) && !linkPhrase.test(subject) && !platform) return null;
  const x = (g.docs.find(p => p.extraction) || {}).extraction || {};
  const numM = (subject + '\n' + body).match(/\binv(?:oice)?\s*(?:no\.?|number|#)?\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/]{2,})/i);
  const totM = body.match(/total[^£$€\d\n]{0,20}([£$€]\s?[\d,]+(?:\.\d{2})?)/i) || body.match(/([£$€]\s?[\d,]+\.\d{2})/);
  return {
    invoice_number: x.invoice_number || (numM ? numM[1] : ''),
    total: x.total_gross != null ? x.total_gross : (totM ? totM[1].replace(/\s/g, '') : ''),
    platform: platform || ''
  };
};

const out = [];
for (const key of order) {
  const g = groups[key];
  const s = g.source;
  const invoices = g.docs.filter(p => p.extraction && p.extraction.is_invoice === true);
  const senderEmail = String(s.from_email || '').toLowerCase();
  const base = {
    outlook_message_id: g.outlook_message_id, internet_message_id: s.message_id || '', sender_email: senderEmail,
    sender_name: String(s.from || '').replace(/<[^>]*>/, '').trim(), subject: s.subject || '', mode, existing_categories: g.categories
  };
  let verdict, issues = [], reviewReasons = [];
  let sup = '', invNo = '', invDate = '', total = null, billTo = '', billToCompany = '';
  let bounceKey = '';
  let linkOnly = false;
  if (!invoices.length) {
    const li = linkInvoice(g);
    if (li) {
      verdict = 'review'; linkOnly = true;
      invNo = String(li.invoice_number || ''); sup = String(base.sender_name || '');
      reviewReasons.push({ code: 'invoice_link_only', message: 'The invoice' + (invNo ? ' ' + invNo : '') + (li.total !== '' ? ' (total ' + li.total + ')' : '') + ' is a download link in the email, not an attachment' + (li.platform ? ' (sent via ' + li.platform + ')' : '') + '. Open the link in the email and download the PDF.' });
    } else {
      verdict = 'not_invoice';
    }
  } else {
    const docIssues = [];
    for (const p of invoices) {
      const x = p.extraction;
      const supplier = x.supplier || {};
      const cur = String(x.currency || 'GBP').toUpperCase();
      const name = (supplier.name || '') ;
      const di = [];
      if (!sup) { sup = name; invNo = x.invoice_number || ''; invDate = x.invoice_date || ''; total = num((x.totals || {}).gross); billTo = (x.addressed_to || {}).name || ''; billToCompany = matchCompany(billTo); }
      // internal reasons (never sent to the supplier)
      if (p.extraction_error) reviewReasons.push({ code: 'extraction_failed', message: 'The invoice could not be read by the AI.' });
      if (num(x.legibility_confidence) !== null && num(x.legibility_confidence) < legMin) reviewReasons.push({ code: 'low_legibility', message: 'Hard to read (confidence ' + x.legibility_confidence + ').' });
      // 1. formatted correctly
      if (!name) di.push({ code: 'no_supplier', message: 'The supplier name is not shown on the invoice.' });
      if (!x.invoice_number) di.push({ code: 'no_invoice_number', message: 'There is no invoice number.' });
      if (!x.invoice_date) di.push({ code: 'no_invoice_date', message: 'There is no invoice date.' });
      const totalGross = num((x.totals || {}).gross);
      if (totalGross === null) di.push({ code: 'no_total', message: 'The invoice total is not shown.' });
      const lines = Array.isArray(x.lines) ? x.lines : [];
      if (!lines.length) di.push({ code: 'no_lines', message: 'The invoice has no itemised lines.' });
      // 2. addressed to the right company
      if (!companyNorm.length) reviewReasons.push({ code: 'no_company_list', message: 'No company names configured, so the bill-to was not checked.' });
      else {
        const bt = normName((x.addressed_to || {}).name);
        if (!bt) di.push({ code: 'bill_to_missing', message: 'The invoice is not addressed to a company.' });
        else if (!matchCompany(bt) && !aliasFileOk) reviewReasons.push({ code: 'alias_file_unreadable', message: 'Addressed to "' + (x.addressed_to || {}).name + '", which is not on the company list, and the company aliases could not be read, so it was not bounced.' });
        else if (!matchCompany(bt)) di.push({ code: 'bill_to_wrong', message: 'The invoice is addressed to "' + (x.addressed_to || {}).name + '", which is not one of our companies.' });
      }
      // 3. each line states a property and its own cost (credit notes are only checked for format)
      if (x.document_type !== 'credit_note' && lines.length) {
        const amounts = lines.map(l => {
          const gross = num(l.gross); if (gross !== null) return gross;
          const n = num(l.net), v = num(l.vat); return n !== null ? r2(n + (v || 0)) : null;
        });
        if (lines.length === 1 && amounts[0] === null && totalGross !== null) amounts[0] = totalGross;
        const noAmt = lines.filter((l, i) => amounts[i] === null);
        if (noAmt.length) di.push({ code: 'no_line_amounts', message: 'The cost is not shown for each line (' + noAmt.length + ' of ' + lines.length + ' lines have no amount).', lines: noAmt.map(l => ({ text: l.description || '(no description)', amount: null })) });
        const missing = [], incomplete = [];
        lines.forEach((l, i) => {
          const st = refStatus(l.property_reference_as_written);
          const item = { text: l.description || '(no description)', amount: amounts[i], reference: l.property_reference_as_written || '' };
          if (st === 'missing') missing.push(item); else if (st === 'incomplete') incomplete.push(item);
        });
        if (missing.length) di.push({ code: 'property_missing', message: 'These lines do not say which property they are for.', lines: missing });
        if (incomplete.length) di.push({ code: 'property_incomplete', message: 'These lines give only part of a property address (for example a number with no street or name).', lines: incomplete });
        // adds up? (our check, not the supplier's problem)
        const sum = r2(amounts.reduce((a, b) => a + (b || 0), 0));
        if (totalGross !== null && !amounts.some(a => a === null) && Math.abs(sum - totalGross) > 0.02) reviewReasons.push({ code: 'totals_mismatch', message: 'Lines add up to ' + money(sum, cur) + ' but the total is ' + money(totalGross, cur) + '.' });
      }
      if (di.length) docIssues.push({ filename: (p.source || {}).filename || '', invoice_number: x.invoice_number || '', supplier: name, currency: cur, issues: di });
    }
    issues = docIssues;
    const flat = docIssues.reduce((a, d) => a.concat(d.issues), []);
    if (!flat.length && !reviewReasons.length) verdict = 'pass';
    else if (!flat.length) verdict = 'review';
    else if (reviewReasons.length) verdict = 'review';   // when we are unsure we read it right, a person looks first
    else verdict = 'bounce';
    bounceKey = senderEmail + '|' + String(invNo || (invoices[0].source || {}).filename || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    // ---- safety rules: when in doubt, never contact the sender ----
    if (verdict === 'bounce') {
      const dom = senderEmail.split('@')[1] || '';
      if (!senderEmail) { verdict = 'review'; reviewReasons.push({ code: 'no_sender', message: 'No sender address to reply to.' }); }
      else if (internalDomain && dom === internalDomain) { verdict = 'review'; reviewReasons.push({ code: 'internal_sender', message: 'Sent from inside the company, so it was not bounced.' }); }
      else if (blocked.some(b => senderEmail.indexOf(b) >= 0)) { verdict = 'review'; reviewReasons.push({ code: 'automated_sender', message: 'Sent from an automated address that cannot be replied to.' }); }
      else {
        const sentBefore = hist.filter(h => h.bounce_key === bounceKey && sentActions.includes(h.action)).length;
        const sentToday = hist.filter(h => String(h.sender_email || '').toLowerCase() === senderEmail && sentActions.includes(h.action) && now - (Date.parse(h.processed_at || '') || 0) < 86400000).length;
        if (sentBefore >= maxPerInvoice) { verdict = 'review'; reviewReasons.push({ code: 'already_asked', message: 'This sender has already been asked ' + sentBefore + ' time(s) about this invoice.' }); }
        else if (sentToday >= maxPerSenderDay) { verdict = 'review'; reviewReasons.push({ code: 'daily_limit', message: 'Daily bounce limit reached for this sender.' }); }
      }
    }
  }

  // ---- the message to the supplier ----
  let bounce = null;
  if (verdict === 'bounce') {
    const F = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#101828;';
    const TH = 'text-align:left;background:#f2f4f7;padding:6px 10px;border:1px solid #d0d5dd;';
    const TD = 'padding:6px 10px;border:1px solid #d0d5dd;vertical-align:top;';
    let h = '<div style="' + F + '"><p>Hello,</p>';
    h += '<p>Thank you for your invoice' + (invNo ? ' <b>' + esc(invNo) + '</b>' : '') + '. We have not been able to process it because the details below are missing or unclear. Please send a corrected invoice by replying to this email.</p>';
    for (const d of issues) {
      if (issues.length > 1) h += '<p><b>' + esc(d.filename || d.invoice_number || 'Invoice') + '</b></p>';
      h += '<ul>';
      for (const i of d.issues) {
        h += '<li>' + esc(i.message);
        if (i.lines && i.lines.length) {
          h += '<table style="border-collapse:collapse;margin:6px 0;' + F + 'font-size:13px;"><tr><th style="' + TH + '">Line on your invoice</th><th style="' + TH + 'text-align:right;">Amount</th></tr>' +
            i.lines.slice(0, 40).map(l => '<tr><td style="' + TD + '">' + esc(l.text) + '</td><td style="' + TD + 'text-align:right;">' + (l.amount === null || l.amount === undefined ? '-' : esc(money(l.amount, d.currency))) + '</td></tr>').join('') + '</table>';
        }
        h += '</li>';
      }
      h += '</ul>';
    }
    h += '<p><b>What we need on the corrected invoice</b></p><ul>' +
      '<li>It is addressed to the company the work was done for. Our companies are: ' + esc(acceptedNames.join(', ')) + '.</li>' +
      '<li>Every line shows the <b>property</b> (full address or property name) and its own <b>amount</b>, so each cost can be recorded against the correct property.</li>' +
      '<li>Invoice number, invoice date and total are shown.</li></ul>';
    h += '<p>If you believe this message is wrong, just reply and tell us. This request was produced by our automated invoice check, and a member of the accounts team reads the replies.</p>';
    h += '<p>Kind regards,<br>' + esc(cfg.sender_name || 'Hinkley Homes Accounts') + '</p></div>';
    bounce = { to: senderEmail, subject: 'Action needed: please reissue invoice ' + (invNo || '') + (sup ? ' from ' + sup : ''), html: h };
  }

  const catMap = { pass: cfg.cat_pass, not_invoice: cfg.cat_not_invoice, review: cfg.cat_review, bounce: mode === 'live' ? cfg.cat_bounced : mode === 'draft' ? cfg.cat_drafted : cfg.cat_shadow };
  const newCat = catMap[verdict] || '';
  const cats = (g.categories || []).filter(c => String(c).indexOf('n8n:') !== 0).concat(newCat ? [newCat] : []);
  const action = verdict === 'bounce' ? (mode === 'live' ? 'bounce_sent' : mode === 'draft' ? 'draft_created' : 'shadow_proposed') : 'none';
  const allIssues = issues.reduce((a, d) => a.concat(d.issues), []).concat(reviewReasons);
  const ccs = String(cfg.bounce_cc || '').split(',').map(a => a.trim()).filter(Boolean).map(a => ({ emailAddress: { address: a } }));
  out.push({
    json: Object.assign(base, {
      verdict, action, supplier_name: sup, invoice_number: invNo, invoice_date: invDate, total_gross: total, bill_to: billTo, bill_to_company: billToCompany,
      issue_codes: allIssues.map(i => i.code).join(', '), issues_json: JSON.stringify({ issues, review: reviewReasons }), review_reasons: reviewReasons,
      bounce_key: verdict === 'bounce' ? bounceKey : bounceKey || '', new_category: newCat, categories_body: (verdict === 'bounce' || linkOnly) ? { categories: cats, isRead: false } : { categories: cats },
      is_bounce: verdict === 'bounce',
      reply_body: bounce ? { message: Object.assign({ body: { contentType: 'HTML', content: bounce.html } }, ccs.length ? { ccRecipients: ccs } : {}) } : null,
      shadow_mail: bounce ? { message: Object.assign(noreplyAddress ? { from: { emailAddress: { address: noreplyAddress } } } : {}, { subject: '[SHADOW] Would ask ' + senderEmail + ' to reissue: ' + (sup || 'invoice') + ' ' + invNo, body: { contentType: 'HTML', content: '<p style="font-family:Arial,sans-serif;font-size:13px;color:#b54708"><b>Shadow mode: nothing was sent to the supplier.</b> Issues found: ' + esc(allIssues.map(i => i.code).join(', ')) + '. This is the message that would be sent to ' + esc(senderEmail) + ':</p><hr>' + bounce.html }, toRecipients: [{ emailAddress: { address: cfg.reviewer_email } }] }), saveToSentItems: false } : null,
      processed_at: new Date().toISOString()
    })
  });
}
return out;

// Has this exact document been read before? Same file bytes (or same bill text) = same reading, no LLM call.
// Saved readings come from Supabase (document_readings), looked up just before.
const items = $input.all();
let cache = {};
try { cache = $('Look up saved readings').first().json.readings || {}; } catch (e) { cache = {}; /* lookup failed: read everything */ }
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const hit = it.json.doc_hash ? cache[it.json.doc_hash] : null;
  const ex = hit && typeof hit === 'object' ? hit : null;
  out.push({ json: Object.assign({}, it.json, { cache_hit: !!ex, cached_extraction: ex }), binary: it.binary, pairedItem: { item: i } });
}
return out;

// Cache hit: hand the saved reading straight to the parser. No file, no LLM call.
const items = $input.all();
return items.map((it, i) => ({ json: { cached_extraction: it.json.cached_extraction }, pairedItem: { item: i } }));

// Save every NEW reading once, so the same document is never paid for twice.
const out = [];
const seen = new Set();
for (const it of $input.all()) {
  const p = (it.json || {}).payload || {};
  if (p.from_cache || !p.extraction || p.extraction_error || !p.doc_hash || seen.has(p.doc_hash)) continue;
  seen.add(p.doc_hash);
  out.push({ json: { doc_hash: p.doc_hash, extraction_json: JSON.stringify(p.extraction), model: p.model || '', provider: p.extraction_provider || '', extracted_at: new Date().toISOString() } });
}
return out;

// Lets through only emails NOT already in invoice_intake_checks (looked up in Supabase just before).
const norm = v => (v === null || v === undefined) ? '' : String(v).trim().toLowerCase();
const found = ($('Find emails already checked').first().json || {}).ids;
if (!Array.isArray(found)) throw new Error('Could not look up which emails were already checked in Supabase.');
const seen = new Set(found.map(norm));
const out = [];
$input.all().forEach((it, i) => {
  if (!seen.has(norm((it.json || {}).internetMessageId))) out.push({ json: it.json, binary: it.binary, pairedItem: { item: i } });
});
return out;

// Collects this run's checks for Supabase (invoice_intake_checks), with tidy dates and amounts.
const dateOk = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(Date.parse(v)) && new Date(v + 'T00:00:00Z').toISOString().slice(0, 10) === v;
const amount = v => { const n = typeof v === 'number' ? v : (typeof v === 'string' && v.trim() ? Number(v.replace(/[£$€,\s]/g, '')) : NaN); return Number.isFinite(n) ? Math.round(n * 100) / 100 : null; };
const rows = [];
$input.all().forEach((it, i) => {
  const c = $('Check invoice').itemMatching(i).json || {};
  const id = c.internet_message_id || c.outlook_message_id;
  if (!id) return;
  let issues = {};
  try { issues = JSON.parse(c.issues_json || '{}'); } catch (e) { issues = {}; }
  rows.push({
    processed_at: c.processed_at || null,
    internet_message_id: id,
    outlook_message_id: c.outlook_message_id || null,
    sender_email: c.sender_email || null,
    subject: c.subject || null,
    supplier_name: c.supplier_name || null,
    invoice_number: c.invoice_number || null,
    invoice_date: dateOk(c.invoice_date) ? c.invoice_date : null,
    total_gross: amount(c.total_gross),
    bill_to: c.bill_to || null,
    verdict: c.verdict || 'not_invoice',
    issue_codes: c.issue_codes || null,
    action: c.action || null,
    mode: c.mode || null,
    bounce_key: c.bounce_key || null,
    issues,
  });
});
if (!rows.length) return [];
return [{ json: { rows } }];

// Collects the new readings for Supabase (document_readings).
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  let extraction = null;
  try { extraction = JSON.parse(j.extraction_json); } catch (e) { extraction = null; }
  if (j.doc_hash && extraction && typeof extraction === 'object') rows.push({ doc_hash: j.doc_hash, extraction, model: j.model, provider: j.provider, extracted_at: j.extracted_at });
}
if (!rows.length) return [];
return [{ json: { rows } }];

// One row per email the check sent for review, for the app's invoice_intake_reviews table
// (Invoices > For review). Saved straight to Supabase, so the values are tidied here.
// The Outlook link and received time come from the trigger (matched by Internet message id).
const trig = {};
for (const t of $('Outlook trigger (accounts inbox)').all()) {
  const j = t.json || {};
  if (j.internetMessageId) trig[j.internetMessageId] = j;
  if (j.id) trig[j.id] = j;
}
const txt = (v, max) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, max) : (typeof v === 'number' ? String(v) : null);
const amt = v => { const n = typeof v === 'number' ? v : (typeof v === 'string' && v.trim() ? Number(v.replace(/[£$€,\s]/g, '')) : NaN); return Number.isFinite(n) ? Math.round(n * 100) / 100 : null; };
const out = [];
$input.all().forEach((it, i) => {
  const c = it.json || {};
  const id = txt(c.internet_message_id, 500) || txt(c.outlook_message_id, 500);
  if (!id) return;
  const t = trig[c.internet_message_id] || trig[c.outlook_message_id] || {};
  let parsed = {};
  try { parsed = JSON.parse(c.issues_json || '{}'); } catch (e) { parsed = {}; }
  const docs = Array.isArray(parsed.issues) ? parsed.issues : [];
  const issues = [];
  for (const d of docs) for (const x of (d.issues || [])) {
    const message = txt((docs.length > 1 && d.filename ? d.filename + ': ' : '') + (x.message || ''), 1000);
    if (message) issues.push({ code: txt(x.code, 60) || 'other', message, lines: (x.lines || []).slice(0, 40).map(l => ({ text: txt(l.text, 500) || '(no description)', amount: amt(l.amount) })) });
  }
  const reasons = (Array.isArray(c.review_reasons) ? c.review_reasons : (parsed.review || [])).slice(0, 50)
    .map(r => ({ code: txt((r || {}).code, 60) || 'other', message: txt((r || {}).message, 1000) })).filter(r => r.message);
  const link = txt(t.webLink, 2000);
  const date = txt(c.invoice_date, 10);
  const received = txt(t.receivedDateTime, 40);
  const cur = txt((docs[0] && docs[0].currency) || 'GBP', 3);
  out.push({
    json: {
      internet_message_id: id,
      outlook_message_id: txt(c.outlook_message_id, 500),
      // Only Outlook links: the app opens it in a new tab.
      web_link: link && /^https:\/\/outlook\.(office365|office|live)\.com\//i.test(link) ? link : null,
      received_at: received && !isNaN(Date.parse(received)) ? new Date(received).toISOString() : null,
      sender_email: (txt(c.sender_email, 300) || '').toLowerCase() || null,
      sender_name: txt(c.sender_name, 300),
      subject: txt(c.subject, 500),
      supplier_name: txt(c.supplier_name, 300),
      invoice_number: txt(c.invoice_number, 100),
      invoice_date: date && /^\d{4}-\d{2}-\d{2}$/.test(date) && !isNaN(Date.parse(date)) ? date : null,
      total: amt(c.total_gross),
      currency: cur && /^[A-Za-z]{3}$/.test(cur) ? cur.toUpperCase() : 'GBP',
      bill_to: txt(c.bill_to, 300),
      bill_to_company: txt(c.bill_to_company, 200),
      reasons,
      issues
    },
    pairedItem: { item: i }
  });
});
return out;

parameters.query:
select coalesce(jsonb_agg(internet_message_id), '[]'::jsonb) as ids
from public.invoice_intake_checks
where internet_message_id in (select jsonb_array_elements_text($1::jsonb));

select coalesce(jsonb_object_agg(doc_hash, extraction), '{}'::jsonb) as readings
from public.document_readings
where doc_hash in (select jsonb_array_elements_text($1::jsonb));

insert into public.document_readings (doc_hash, extraction, model, provider, created_at)
select doc_hash, extraction, nullif(model, ''), nullif(provider, ''), coalesce(extracted_at, now())
from jsonb_to_recordset($1::jsonb) as r(doc_hash text, extraction jsonb, model text, provider text, extracted_at timestamptz)
where coalesce(doc_hash, '') <> '' and extraction is not null
on conflict (doc_hash) do nothing;

