// One item per invoice document to keep (passed, bounced or for review): the file it came in,
// named "date supplier number", for SharePoint > invoice_files_folder > year-month.
const cfg = $('Config').first().json;
const KEEP = ['pass', 'bounce', 'review'];
const EXT = { 'application/pdf': 'pdf', 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx', 'application/vnd.oasis.opendocument.text': 'odt' };
const clean = v => String(v || '').replace(/[\\/:*?"<>|#%&{}~\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
const docs = {};
for (const it of $('Parse extraction').all()) {
  const p = (it.json || {}).payload || {};
  const id = (p.source || {}).message_id || '';
  (docs[id] = docs[id] || []).push(p);
}
const out = [];
for (const it of $input.all()) {
  const c = it.json || {};
  if (!KEEP.includes(c.verdict) || !c.internet_message_id) continue;
  const month = String(c.processed_at || new Date().toISOString()).slice(0, 7);
  const seen = new Set();
  for (const p of docs[c.internet_message_id] || []) {
    const s = p.source || {};
    const x = p.extraction;
    if (!p.file_base64 || (x && x.is_invoice !== true) || seen.has(p.doc_hash)) continue;
    seen.add(p.doc_hash);
    const mime = String(s.mime_type || 'application/octet-stream');
    const orig = String(s.filename || '');
    const ext = (orig.match(/\.([a-z0-9]{2,5})$/i) || [])[1] || EXT[mime] || 'bin';
    const label = [x && x.invoice_date, x && (x.supplier || {}).name, x && x.invoice_number].map(clean).filter(Boolean).join(' ');
    const name = (label || clean(orig.replace(/\.[a-z0-9]{2,5}$/i, '')) || 'invoice') + '.' + ext.toLowerCase();
    const path = String(cfg.invoice_files_folder || 'Hinkley Data Tables/Invoices').split('/').filter(Boolean).concat([month, name]);
    out.push({
      json: {
        internet_message_id: c.internet_message_id, file_name: name, mime_type: mime,
        upload_url: 'https://graph.microsoft.com/v1.0/drives/' + cfg.invoice_files_drive_id + '/root:/' + path.map(encodeURIComponent).join('/') + ':/content?@microsoft.graph.conflictBehavior=rename'
      },
      binary: { data: await this.helpers.prepareBinaryData(Buffer.from(p.file_base64, 'base64'), name, mime) }
    });
  }
