// The invoice link in each checked invoice email (Xero, QuickBooks, Invoice Simple, Square...),
// so the app can open it. The link with "invoice" in its text or address, on a known invoicing site, wins.
const KEEP = ['pass', 'bounce', 'review'];
const PLATFORMS = /(^|\.)(xero\.com|intuit\.com|quickbooks\.com|invoicesimple\.com|getinvoicesimple\.com|squareup\.com|square\.link|sumup\.com|zoho\.com|zoho\.eu|freeagent\.com|stripe\.com|paypal\.com|invoice2go\.com|waveapps\.com|freshbooks\.com|invoicehome\.com|kashflow\.com|clearbooks\.co\.uk|sage\.com|pandle\.com|invoiceninja\.com|zervant\.com|bill\.com)$/i;
const SKIP = /unsubscribe|preferences|privacy|terms|cookie|facebook|twitter|linkedin|instagram|youtube|apps\.apple|play\.google|mailto:/i;
const trig = {};
for (const t of $('Outlook trigger (accounts inbox)').all()) {
  const j = t.json || {};
  if (j.internetMessageId) trig[j.internetMessageId] = j;
  if (j.id) trig[j.id] = j;
}
const best = html => {
  let top = null;
  const re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const url = m[1].trim().replace(/&amp;/g, '&');
    const text = m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    let u; try { u = new URL(url); } catch (e) { continue; }
    if (u.protocol !== 'https:' || SKIP.test(url) || SKIP.test(text)) continue;
    let score = 0;
    if (PLATFORMS.test(u.hostname)) score += 2;
    if (/\b(view|download|open|see|pay|access)\b.{0,25}\b(invoice|bill)\b|\binvoice\b/i.test(text)) score += 2;
    if (/invoice/i.test(u.pathname + u.search)) score += 1;
    if (score >= 2 && (!top || score > top.score)) top = { url, score };
  }
  if (!top) {   // plain-text emails: a bare invoice address on a known invoicing site
    for (const url of (html.replace(/<[^>]+>/g, ' ').match(/https:\/\/[^\s"'<>)]+/g) || [])) {
      let u; try { u = new URL(url); } catch (e) { continue; }
      if (!SKIP.test(url) && PLATFORMS.test(u.hostname) && /inv|bill|pay/i.test(u.pathname + u.search)) { top = { url }; break; }
    }
  }
  return top ? top.url : null;
};
const rows = [];
for (const it of $input.all()) {
  const c = it.json || {};
  if (!KEEP.includes(c.verdict) || !c.internet_message_id) continue;
  const t = trig[c.internet_message_id] || trig[c.outlook_message_id] || {};
  const body = t.body;
  const url = best(String(typeof body === 'string' ? body : (body && body.content) || ''));
  if (url && url.length <= 2000) rows.push({ internet_message_id: c.internet_message_id, kind: 'link', name: null, url });
}
if (!rows.length) return [];
return [{ json: { rows } }];

